import { MakeLogicType, connect, kea, path, selectors } from 'kea'

import { FEATURE_FLAGS } from 'lib/constants'
import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { featureFlagLogic, type FeatureFlagsSet } from 'lib/logic/featureFlagLogic'

import type { IntegrationType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface selfDrivingGitlabLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    providerIntegrations: IntegrationType[] | null // integrationsLogic
    gitlabProjects: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface selfDrivingGitlabLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        gitlabProjects: (featureFlags: FeatureFlagsSet, providerIntegrations: IntegrationType[] | null) => string[]
    }
}

export type selfDrivingGitlabLogicType = MakeLogicType<
    selfDrivingGitlabLogicValues,
    {},
    Record<string, any>,
    selfDrivingGitlabLogicMeta
>

// Self-driving clones and opens merge requests through gitlab.com only, so a self-managed GitLab connection does not count.
const GITLAB_COM_HOSTNAME = 'https://gitlab.com'

/** The gitlab.com projects Self-driving can work in: one per GitLab connection, empty while the flag is off. */
export const selfDrivingGitlabLogic = kea<selfDrivingGitlabLogicType>([
    path(['products', 'signals', 'inbox', 'logics', 'selfDrivingGitlabLogic']),
    connect(() => ({
        values: [featureFlagLogic, ['featureFlags'], integrationsLogic, ['providerIntegrations']],
    })),
    selectors({
        gitlabProjects: [
            (s) => [s.featureFlags, s.providerIntegrations],
            (featureFlags: FeatureFlagsSet, providerIntegrations: IntegrationType[] | null): string[] => {
                if (!featureFlags[FEATURE_FLAGS.SELF_DRIVING_GITLAB]) {
                    return []
                }
                return (providerIntegrations ?? []).flatMap((integration) => {
                    const hostname = integration.config?.hostname
                    const project = integration.config?.path_with_namespace
                    return integration.kind === 'gitlab' &&
                        typeof hostname === 'string' &&
                        hostname.trim().replace(/\/+$/, '').toLowerCase() === GITLAB_COM_HOSTNAME &&
                        typeof project === 'string' &&
                        project
                        ? [project]
                        : []
                })
            },
        ],
    }),
])

/** Whether `repository` is one of `gitlabProjects`. GitLab paths are case-insensitive, and reports store them lowercased. */
export function isGitlabProject(repository: string | null | undefined, gitlabProjects: string[]): boolean {
    const normalized = repository?.trim().toLowerCase()
    return !!normalized && gitlabProjects.some((project) => project.toLowerCase() === normalized)
}
